@prefix ex:     <https://example.org/stac/> .

ex:B4-band raster:histogram [
    raster:count 10 ;
    raster:min "0.0"^^xsd:double ;
    raster:max "10000.0"^^xsd:double ;
    raster:buckets 4, 20, 100, 15, 8, 3, 2, 1, 1, 1 ;
